-- IPF base, versión nueva (29/10/2026, dueño): tipo de inspección con tres opciones (Programada, No programada, Otros), campo «Otros (detallar)» y objetivo con respuesta por defecto. La versión anterior queda retirada. No toca personas, empresas, roles ni permisos.
update public.plantillas_versiones v set estado = 'retirada' from public.plantillas p where v.plantilla_id = p.id and p.empresa_id is null and p.codigo = 'ipf' and v.estado = 'vigente';
with b as (select id from public.plantillas where empresa_id is null and codigo = 'ipf'), r as (select $j${"version":1,"firmas":[{"clave":"inspectores","titulo":"Responsable(s) de la inspección","obligatoria":true,"externo":true,"minimo":1},{"clave":"responsable_registro","titulo":"Responsable del registro","obligatoria":true,"externo":false,"minimo":1}],"reglas":[{"tipo":"filas","etiqueta":"Con condiciones inseguras","seccion":"condiciones"}],"resultado_defecto":"Conforme","puntaje":false,"na_favorable":true,"hallazgo_vencimiento":false,"observacion_general":true,"secciones":[{"clave":"datos","titulo":"Datos de la inspección","puntos":[{"clave":"IPF-A01","texto":"Responsable del área","tipo":"persona","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-A02","texto":"Tipo de inspección","tipo":"lista","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false,"opciones":["Programada","No programada","Otros"]},{"clave":"IPF-A04","texto":"Otros (detallar el tipo de inspección)","tipo":"texto","obligatorio":false,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-A03","texto":"Objetivo de la inspección","tipo":"texto_largo","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false,"valor_defecto":"Identificar condiciones y actos inseguros en el área"}]},{"clave":"pregunta","titulo":"Condiciones inseguras","puntos":[{"clave":"IPF-01","texto":"¿Se identificaron condiciones inseguras?","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false}]},{"clave":"condiciones","titulo":"Condición insegura","puntos":[{"clave":"IPF-C01","texto":"Peligro identificado","tipo":"texto","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-C02","texto":"Riesgo asociado","tipo":"texto","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-C03","texto":"Evidencia (foto)","tipo":"foto","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-C04","texto":"Acción de mejora","tipo":"texto_largo","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-C05","texto":"Responsable","tipo":"persona","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-C06","texto":"Plazo","tipo":"fecha","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false}],"repetible":{"activa_con":"IPF-01","minimo":1,"genera_hallazgo":true}},{"clave":"cierre","titulo":"Cierre","puntos":[{"clave":"IPF-R01","texto":"Resultado de la inspección","tipo":"texto_largo","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-R02","texto":"Causas de los resultados desfavorables (escribe «No aplica» si no hubo)","tipo":"texto_largo","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"IPF-R03","texto":"Conclusiones y recomendaciones","tipo":"texto_largo","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false}]}]}$j$::jsonb as receta)
insert into public.plantillas_versiones (plantilla_id, numero, estado, logo, receta, huella, publicado_en)
select b.id, (select coalesce(max(numero), 0) + 1 from public.plantillas_versiones where plantilla_id = b.id), 'vigente', 'positivo', r.receta,
  encode(extensions.digest(convert_to(r.receta::text, 'UTF8'), 'sha256'), 'hex'), now() from b, r;
update public.plantillas set actualizado_en = now() where empresa_id is null and codigo = 'ipf';
